"use strict";

const FormTemplates = (() => {

    function esc(a) {
        return String(a ?? "").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
    }

    function val(o, k, def = "") {
        return esc(o?.[k] ?? def);
    }

    function opt(v, label, cur) {
        const sel = cur === v ? " selected" : "";
        return `<option value="${esc(v)}"${sel}>${esc(label)}</option>`;
    }

    return {

        // ── Form KK + data kepala keluarga ────────────────────────
        kk: function(data = null, rtList = [], role = "rt", perumahanList = [], clusterList = []) {
            const isEdit = !!data;

            // RT options — sekarang include data RW
            const rtOptions = rtList.map(rt =>
                `<option value="${esc(String(rt.id))}"
                        data-kode-rt="${esc(rt.kode_rt)}"
                        data-kode-rw="${esc(rt.kode_rw ?? '')}"
                        data-rw-id="${esc(String(rt.rw_id ?? ''))}"
                        ${String(data?.rt_id ?? '') === String(rt.id) ? 'selected' : ''}>
                    RT ${esc(rt.kode_rt)}
                </option>`
            ).join("");

            // Opsi perumahan
            const perumahanOptions = perumahanList.map(p => {
                return opt(String(p.id), p.nama_perumahan, String(data?.perumahan_id ?? ""));
            }).join("");

            // Opsi cluster — filter berdasarkan perumahan_id jika ada
            const selectedPerumahanId = data?.perumahan_id ?? "";
            const filteredClusters = selectedPerumahanId
                ? clusterList.filter(c => String(c.perumahan_id) === String(selectedPerumahanId))
                : [];
            const clusterOptions = filteredClusters.map(c =>
                opt(String(c.id), c.nama_cluster, String(data?.cluster_id ?? ""))
            ).join("");

            const agamaOptions = ["Islam","Kristen","Katolik","Hindu","Buddha","Konghucu","Lainnya"]
                .map(a => opt(a, a, "")).join("");

            /*const pendidikanOptions = [
                ["tidak_sekolah","Tidak Sekolah"],["sd","SD / Sederajat"],
                ["smp","SMP / Sederajat"],["sma","SMA / Sederajat"],
                ["d3","Diploma (D3)"],["s1","Sarjana (S1)"],
                ["s2","Magister (S2)"],["s3","Doktor (S3)"],
            ].map(([v,l]) => opt(v, l, "")).join("");*/

            const statusKawinOptions = [
                ["belum_kawin","Belum Kawin"],["kawin","Kawin"],
                ["cerai_hidup","Cerai Hidup"],["cerai_mati","Cerai Mati"],
            ].map(([v,l]) => opt(v, l, "")).join("");

            return `
<form id="formKk" novalidate autocomplete="off">
    <input type="hidden" id="kkEditUuid" value="${val(data,"uuid")}">
    <!-- ── Data Kepala Keluarga (hanya saat tambah baru) ── -->
    <p class="fw-semibold small text-muted text-uppercase mb-3" style="letter-spacing:.06em">
        <i class="bx bx-user me-1"></i>Data Sesuai KK
    </p>
    <div class="row g-3 mb-3">
        <div class="col-sm-6">
            <label class="form-label fw-semibold" for="kkNoKk">
                Nomor KK <span class="text-danger">*</span>
            </label>
            <input type="text" class="form-control font-monospace" id="kkNoKk"
                name="no_kk" maxlength="16" inputmode="numeric"
                placeholder="16 digit nomor KK"
                value="${val(data,"no_kk")}"
                ${isEdit ? "readonly" : ""} required>
            <div class="form-text text-muted">
                <i class="mdi mdi-lock-outline me-1"></i>Disimpan terenkripsi
            </div>
            <div class="invalid-feedback" id="errKkNoKk"></div>
        </div>
        <div class="col-sm-6">
            <label class="form-label fw-semibold" for="kkKepala">
                Nama Kepala Keluarga <span class="text-danger">*</span>
            </label>
            <input type="text" class="form-control" id="kkKepala"
                name="kepala_keluarga" placeholder="Sesuai KTP"
                value="${val(data,"kepala_keluarga")}" required>
            <div class="invalid-feedback" id="errKkKepala"></div>
        </div>
    </div>
    <div class="mb-3">
        <label class="form-label fw-semibold" for="kkAlamat">Alamat <span class="text-muted small">(sesuai KK)</span></label>
        <textarea class="form-control" id="kkAlamat" name="alamat" rows="2" placeholder="Jl. Contoh No. 1">${val(data,"alamat")}</textarea>
    </div>

    <!-- ── Data Perumahan (hanya saat tambah baru) ── -->
    <hr class="my-3">
    <p class="fw-semibold small text-muted text-uppercase mb-3" style="letter-spacing:.06em">
        <i class="bx bx-user me-1"></i>Data Perumahan
    </p>
    <div class="row g-3 mb-3">
        <div class="col-sm-6">
            <label class="form-label fw-semibold" for="kkPerumahanId">Perumahan</label>
            <select class="form-select" id="kkPerumahanId" name="perumahan_id">
                <option value="">-- Pilih Perumahan --</option>
                ${perumahanOptions}
            </select>
        </div>
        <div class="col-sm-4">
            <label class="form-label fw-semibold" for="kkClusterId">Cluster / Blok</label>
            <select class="form-select" id="kkClusterId" name="cluster_id" ${!selectedPerumahanId ? 'disabled' : ''}>
                <option value="">-- Pilih Cluster --</option>
                ${clusterOptions}
            </select>
        </div>
        <div class="col-sm-2">
            <label class="form-label fw-semibold" for="kkNoRumah">No. Rumah</label>
            <input type="text" class="form-control" id="kkNoRumah" name="no_rumah" placeholder="Contoh: 10, A5, B-12" value="${val(data,"no_rumah")}">
        </div>
    </div>
    ${role !== "rt" ? `
    <div class="row g-3 mb-3">
        <div class="col-sm-6">
            <label class="form-label fw-semibold" for="kkRtId">
                RT <span class="text-danger">*</span>
            </label>
            <select class="form-select" id="kkRtId" name="rt_id" ${isEdit ? "disabled" : ""} required>
                <option value="">-- Pilih RT --</option>
                ${rtOptions}
            </select>
            <div class="invalid-feedback" id="errKkRtId"></div>
        </div>
        <div class="col-sm-6">
            <label class="form-label fw-semibold" for="kkRwDisplay">RW</label>
            <div class="input-group">
                <span class="input-group-text">RW</span>
                <input type="text" class="form-control" id="kkRwDisplay" name="rw_display" value="${val(data,"rw_display")}" readonly>
            </div>
        </div>
    </div>` : ""}
    <div class="row g-3 mb-3 d-none">
        <div class="col-sm-6">
            <label class="form-label fw-semibold" for="kkRtDisplay">
                RT <span class="text-muted small">(tampilan)</span>
            </label>
            <div class="input-group">
                <span class="input-group-text">RT</span>
                <input type="text" class="form-control" id="kkRtDisplay" name="rt_display" value="${val(data,"rt_display")}" readonly>
            </div>
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label fw-semibold" for="kkKodePos">Kode Pos</label>
        <input type="text" class="form-control" id="kkKodePos"
               name="kode_pos" maxlength="10" inputmode="numeric"
               placeholder="12345" value="${val(data,"kode_pos")}">
    </div>

    ${isEdit ? `
    <div class="mb-3">
        <label class="form-label fw-semibold">Status KK</label>
        <select class="form-select" id="kkIsActive" name="is_active">
            ${opt("1","Aktif",String(data?.is_active ?? "1"))}
            ${opt("0","Tidak Aktif",String(data?.is_active ?? "1"))}
        </select>
    </div>` : `
    <!-- ── Data Pribadi (hanya saat tambah baru) ── -->
    <hr class="my-3">
    <p class="fw-semibold small text-muted text-uppercase mb-3" style="letter-spacing:.06em">
        <i class="bx bx-user me-1"></i>Data Kepala Keluarga
    </p>

    <div class="mb-3">
        <label class="form-label fw-semibold" for="kkNik">
            NIK <span class="text-danger">*</span>
        </label>
        <div class="input-group">
            <input type="text" class="form-control" id="kkNik" name="nik" maxlength="16" inputmode="numeric" placeholder="16 digit NIK" required>
            <span class="input-group-text">
                <i class="mdi mdi-reload spin d-none" id="kkNikLoader"></i>
                <i class="mdi mdi-check text-success d-none" id="kkNikOk"></i>
                <i class="mdi mdi-close text-danger d-none" id="kkNikErr"></i>
            </span>
        </div>
        <div class="form-text text-muted"><i class="mdi mdi-lock-outline me-1"></i>Disimpan terenkripsi</div>
        <div class="invalid-feedback" id="errKkNik"></div>
    </div>

    <div class="row g-3 mb-3">
        <div class="col-md-6">
            <label class="form-label fw-semibold" for="kkTempatLahir">Tempat Lahir</label>
            <input type="text" class="form-control" id="kkTempatLahir"
                   name="tempat_lahir" placeholder="Kota kelahiran">
        </div>
        <div class="col-md-6">
            <label class="form-label fw-semibold" for="kkTglLahir">Tanggal Lahir</label>
            <input type="text" class="form-control" id="kkTglLahir" name="tanggal_lahir">
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label fw-semibold">Jenis Kelamin</label>
        <div class="d-flex gap-4 pt-1">
            <div class="form-check">
                <input class="form-check-input" type="radio" id="kkJkL"
                       name="jenis_kelamin" value="L" checked>
                <label class="form-check-label" for="kkJkL">Laki-laki</label>
            </div>
            <div class="form-check">
                <input class="form-check-input" type="radio" id="kkJkP"
                       name="jenis_kelamin" value="P">
                <label class="form-check-label" for="kkJkP">Perempuan</label>
            </div>
        </div>
    </div>

    <div class="row g-3 mb-3">
        <div class="col-md-6">
            <label class="form-label fw-semibold" for="kkAgama">Agama</label>
            <select class="form-select" id="kkAgama" name="agama">
                <option value="">-- Pilih Agama --</option>
                ${agamaOptions}
            </select>
        </div>
        <div class="col-md-6">
            <label class="form-label fw-semibold" for="kkStatusKawin">Status Perkawinan</label>
            <select class="form-select" id="kkStatusKawin" name="status_perkawinan">
                <option value="">-- Pilih Status --</option>
                ${statusKawinOptions}
            </select>
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label fw-semibold" for="kkTelp">No HP / WhatsApp</label>
        <div class="input-group">
            <span class="input-group-text">+62</span>
            <input type="text" class="form-control" id="kkTelp"
                   name="telp" inputmode="numeric" maxlength="14"
                   placeholder="812xxxxxxxx">
        </div>
    </div>

    <div class="row g-3 mb-3">
        <div class="col-md-6">
            <label class="form-label fw-semibold" for="kkStatusHidup">Status Hidup</label>
            <select class="form-select" id="kkStatusHidup" name="status_hidup">
                <option value="hidup" selected>Hidup</option>
                <option value="meninggal">Meninggal</option>
            </select>
        </div>
        <div class="col-md-6">
            <label class="form-label fw-semibold" for="kkStatusDomisili">Status Domisili</label>
            <select class="form-select" id="kkStatusDomisili" name="status_domisili">
                <option value="tetap" selected>Tetap</option>
                <option value="kontrak">Kontrak</option>
                <option value="pindah">Pindah</option>
            </select>
        </div>
    </div>
    `}

</form>`;
        },

        // ── Form Warga (tidak berubah) ────────────────────────────
        warga: function(data = null, kkNama = "") {
            const jkL = "L" === data?.jenis_kelamin ? " checked" : "";
            const jkP = "P" === data?.jenis_kelamin ? " checked" : "";

            const agamaOptions = ["Islam","Kristen","Katolik","Hindu","Buddha","Konghucu","Lainnya"]
                .map(a => opt(a, a, data?.agama)).join("");

            /*const pendidikanOptions = [
                ["tidak_sekolah","Tidak Sekolah"],["sd","SD / Sederajat"],
                ["smp","SMP / Sederajat"],["sma","SMA / Sederajat"],
                ["d3","Diploma (D3)"],["s1","Sarjana (S1)"],
                ["s2","Magister (S2)"],["s3","Doktor (S3)"],
            ].map(([v,l]) => opt(v, l, data?.pendidikan)).join("");*/

            const statusKawinOptions = [
                ["belum_kawin","Belum Kawin"],["kawin","Kawin"],
                ["cerai_hidup","Cerai Hidup"],["cerai_mati","Cerai Mati"],
            ].map(([v,l]) => opt(v, l, data?.status_perkawinan)).join("");

            const statusKkOptions = [
                ["kepala_keluarga","Kepala Keluarga"],["istri","Istri"],
                ["anak","Anak"],["orang_tua","Orang Tua"],["lainnya","Lainnya"],
            ].map(([v,l]) => opt(v, l, data?.status_keluarga)).join("");

            return `
<form id="formWarga" novalidate autocomplete="off">
    <input type="hidden" id="wargaEditUuid" value="${val(data,"uuid")}">

    ${kkNama ? `
    <div class="alert alert-info d-flex gap-2 py-2 small mb-3">
        <i class="bx bx-home-circle flex-shrink-0 mt-1"></i>
        <span>KK: <strong>${esc(kkNama)}</strong></span>
    </div>` : ""}

    <ul class="nav nav-tabs nav-tabs-bordered mb-3" role="tablist">
        <li class="nav-item">
            <button class="nav-link active" data-bs-toggle="tab"
                    data-bs-target="#wTabIdentitas" type="button">
                <i class="bx bx-id-card me-1"></i>Identitas
            </button>
        </li>
        <li class="nav-item">
            <button class="nav-link" data-bs-toggle="tab"
                    data-bs-target="#wTabKependudukan" type="button">
                <i class="bx bx-buildings me-1"></i>Kependudukan
            </button>
        </li>
        <li class="nav-item">
            <button class="nav-link" data-bs-toggle="tab"
                    data-bs-target="#wTabKontak" type="button">
                <i class="bx bx-phone me-1"></i>Kontak
            </button>
        </li>
    </ul>

    <div class="tab-content">

        <div class="tab-pane fade show active" id="wTabIdentitas">
            <div class="mb-3">
                <label class="form-label fw-semibold" for="wNik">
                    NIK <span class="text-danger">*</span>
                </label>
                <div class="input-group">
                    <input type="text" class="form-control font-monospace" id="wNik"
                           name="nik" maxlength="16" inputmode="numeric"
                           placeholder="16 digit NIK"
                           value="${val(data,"nik")}"
                           ${data ? "readonly" : ""} required>
                    <span class="input-group-text">
                        <i class="bx bx-loader-alt spin d-none" id="wNikLoader"></i>
                        <i class="bx bx-check text-success d-none" id="wNikOk"></i>
                        <i class="bx bx-x text-danger d-none" id="wNikErr"></i>
                    </span>
                </div>
                <div class="form-text text-muted"><i class="mdi mdi-lock-outline me-1"></i>Disimpan terenkripsi</div>
                <div class="invalid-feedback" id="errWNik"></div>
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold" for="wNama">
                    Nama Lengkap <span class="text-danger">*</span>
                </label>
                <input type="text" class="form-control" id="wNama"
                       name="nama_lengkap" placeholder="Sesuai KTP"
                       value="${val(data,"nama_lengkap")}" required>
                <div class="invalid-feedback" id="errWNama"></div>
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">
                    Jenis Kelamin <span class="text-danger">*</span>
                </label>
                <div class="d-flex gap-4 pt-1">
                    <div class="form-check">
                        <input class="form-check-input" type="radio" id="wJkL"
                               name="jenis_kelamin" value="L"${jkL}>
                        <label class="form-check-label" for="wJkL">Laki-laki</label>
                    </div>
                    <div class="form-check">
                        <input class="form-check-input" type="radio" id="wJkP"
                               name="jenis_kelamin" value="P"${jkP}>
                        <label class="form-check-label" for="wJkP">Perempuan</label>
                    </div>
                </div>
                <div class="invalid-feedback d-block" id="errWJk"></div>
            </div>

            <div class="row g-3 mb-3">
                <div class="col-md-6">
                    <label class="form-label fw-semibold" for="wTempatLahir">
                        Tempat Lahir <span class="text-danger">*</span>
                    </label>
                    <input type="text" class="form-control" id="wTempatLahir" name="tempat_lahir" placeholder="Kota kelahiran" value="${val(data,"tempat_lahir")}" required>
                    <div class="invalid-feedback" id="errWTempatLahir"></div>
                </div>
                <div class="col-md-6">
                    <label class="form-label fw-semibold" for="kkTglLahir">
                        Tanggal Lahir <span class="text-danger">*</span>
                    </label>
                    <input type="text" class="form-control" id="kkTglLahir" name="tanggal_lahir" required>
                    <div class="invalid-feedback" id="errkkTglLahir"></div>
                </div>
            </div>
        </div>

        <div class="tab-pane fade" id="wTabKependudukan">
            <div class="mb-3">
                <label class="form-label fw-semibold" for="wAgama">
                    Agama <span class="text-danger">*</span>
                </label>
                <select class="form-select" id="wAgama" name="agama" required>
                    <option value="">-- Pilih Agama --</option>
                    ${agamaOptions}
                </select>
                <div class="invalid-feedback" id="errWAgama"></div>
            </div>
            <div class="mb-3">
                <label class="form-label fw-semibold" for="wStatusKawin">
                    Status Perkawinan <span class="text-danger">*</span>
                </label>
                <select class="form-select" id="wStatusKawin" name="status_perkawinan" required>
                    <option value="">-- Pilih Status --</option>
                    ${statusKawinOptions}
                </select>
                <div class="invalid-feedback" id="errWStatusKawin"></div>
            </div>
            <div class="mb-3">
                <label class="form-label fw-semibold" for="wStatusKk">
                    Status dalam Keluarga <span class="text-danger">*</span>
                </label>
                <select class="form-select" id="wStatusKk" name="status_keluarga" required>
                    <option value="">-- Pilih Status --</option>
                    ${statusKkOptions}
                </select>
                <div class="invalid-feedback" id="errWStatusKk"></div>
            </div>

            <div class="row g-3 mb-3">
                <div class="col-md-6">
                    <label class="form-label fw-semibold" for="wStatusHidup">
                        Status Hidup <span class="text-danger">*</span>
                    </label>
                    <select class="form-select" id="wStatusHidup" name="status_hidup" required>
                        ${opt('hidup',     'Hidup',     data?.status_hidup    ?? 'hidup')}
                        ${opt('meninggal', 'Meninggal', data?.status_hidup    ?? 'hidup')}
                    </select>
                </div>
                <div class="col-md-6">
                    <label class="form-label fw-semibold" for="wStatusDomisili">
                        Status Domisili <span class="text-danger">*</span>
                    </label>
                    <select class="form-select" id="wStatusDomisili" name="status_domisili" required>
                        ${opt('tetap',  'Tetap',  data?.status_domisili ?? 'tetap')}
                        ${opt('kontrak', 'Kontrak', data?.status_domisili ?? 'tetap')}
                        ${opt('pindah', 'Pindah', data?.status_domisili ?? 'tetap')}
                    </select>
                </div>
            </div>
        </div>

        <div class="tab-pane fade" id="wTabKontak">
            <div class="alert alert-info d-flex gap-2 py-2 small mb-3">
                <i class="bx bx-info-circle flex-shrink-0 mt-1"></i>
                <span>Data kontak opsional — dienkripsi dan dipakai untuk notifikasi surat.</span>
            </div>
            <div class="mb-3">
                <label class="form-label fw-semibold" for="wHp">No HP / WhatsApp</label>
                <div class="input-group">
                    <span class="input-group-text">+62</span>
                    <input type="text" class="form-control" id="wHp"
                           name="telp" inputmode="numeric" maxlength="14"
                           placeholder="812xxxxxxxx"
                           value="${val(data,"telp")}">
                </div>
                <div class="invalid-feedback" id="errWHp"></div>
            </div>
            <div class="mb-3">
                <label class="form-label fw-semibold" for="wEmail">Email</label>
                <input type="email" class="form-control" id="wEmail"
                       name="email" placeholder="contoh@email.com"
                       value="${val(data,"email")}">
                <div class="invalid-feedback" id="errWEmail"></div>
            </div>
            <div class="mb-3">
                <label class="form-label fw-semibold" for="wKeterangan">Keterangan</label>
                <textarea class="form-control" id="wKeterangan" name="keterangan"
                          rows="2" placeholder="Catatan tambahan (opsional)">${val(data,"keterangan")}</textarea>
            </div>
        </div>

    </div>
</form>`;
        },
    };
})();